(()=>{'use strict';
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const dialog=$('#detail-dialog');
const details={
framework:{label:'JEV / RESEARCH FRAMEWORK',title:'From experiments<br>to continuous estimates.',body:`<p>JEV 将固定预训练模型的区间判断，与同类吸附实验的上下文和近邻证据结合，输出可追溯的连续吸附容量估计。</p><div class="detail-grid"><div class="detail-step"><small>01 / CONTEXT</small><h3>实验上下文</h3><p>使用热解温度、溶液 pH、初始浓度、BET 比表面积、吸附时间和生物炭 pH 六项状态，从同金属标签记录中检索 8 个上下文近邻。</p></div><div class="detail-step"><small>02 / RANGE</small><h3>容量区间判断</h3><p>固定预训练参数的 JEV 输出各容量区间概率 pᵢ 和模型置信判断 c。Pb 的区间边界为 2、8、16、30、60 mg/g，共六个区间。</p></div><div class="detail-step"><small>03 / EVIDENCE</small><h3>双路近邻检索</h3><p>依据 11 项描述符排序候选记录，同时取得全局近邻 QG 与所选容量区间内的近邻 QB。缺失值以候选池统计量填补，并在池内标准化；相同原料来源使用 −1.5 排序偏移。</p></div><div class="detail-step"><small>04 / ESTIMATION</small><h3>对数空间融合</h3><p>在区间约束证据与全局证据之间进行加权，输出连续 Qe，并保留候选记录与模型判断路径。</p></div></div><p class="formula">QF = QB<sup>α</sup> × QG<sup>1−α</sup></p><p>置信判断 c 并不是校准后的连续预测区间。结果的可靠性仍需通过独立留出集和外部实验验证。</p><img src="assets/jev-workflow.svg" alt="JEV 实验上下文、容量区间与双近邻融合流程图">`},
range:{label:'RESEARCH 01 / RANGE INTELLIGENCE',title:'A range before<br>a number.',body:`<p>先建立容量区间判断，再搜索区间内具有实验相似性的候选记录。区间提供局部约束，模型输出的概率分布同时保留判断的不确定性信息。</p><h3>Pb：六个容量区间</h3><p class="formula">2 · 8 · 16 · 30 · 60 <small>mg/g</small></p><p>这些边界划分六个容量区间。示例样本的所选区间为 B3，即 8 ≤ Qe &lt; 16 mg/g；该区间概率为 0.93，模型置信判断 c = 0.91。</p><h3>由判断进入证据检索</h3><p>在 279 条 Pb 候选记录中，有 77 条进入上述区间。对这部分记录继续计算实验描述符相似性，形成局部近邻候选。</p><p>区间概率和 c 描述模型的区间判断，不应被解释为连续 Qe 的校准置信区间。</p>`},
retrieval:{label:'RESEARCH 02 / EMPIRICAL RETRIEVAL',title:'Experiments provide<br>the context.',body:`<p>材料与条件共同决定吸附表现。JEV 通过实验状态检索有标签的上下文记录，并利用更完整的描述符为最终候选排序。</p><div class="detail-grid"><div class="detail-step"><small>CONTEXT / SIX FIELDS</small><h3>六项状态</h3><p>热解温度、溶液 pH、初始浓度、BET 比表面积、吸附时间、生物炭 pH。检索 8 个同金属标签近邻作为实验上下文。</p></div><div class="detail-step"><small>RANKING / ELEVEN DESCRIPTORS</small><h3>十一项描述符</h3><p>最终近邻使用 11 项描述符；缺失值按候选池统计量填补、池内标准化，相同原料来源施加 −1.5 的排序偏移。</p></div></div><h3>每个候选都对应实验记录</h3><p>Pb 案例保留 279 条全局候选、77 条容量区间候选及各自的距离排序。可下载的数据包含容量、区间成员标记和全局／局部近邻标记。</p><a class="outline-button" href="assets/pb-candidate-rank-qe.csv" download>DOWNLOAD CANDIDATES <span>↓</span></a>`},
fusion:{label:'RESEARCH 03 / CONTINUOUS ESTIMATION',title:'Two evidence routes.<br>One traceable estimate.',body:`<p>区间近邻 QB 与全局近邻 QG 分别提供局部与整体证据。JEV 通过对数空间加权融合，将离散的容量区间判断转换为连续估计。</p><p class="formula">QF = QB<sup>α</sup> × QG<sup>1−α</sup></p><h3>Pb 可追溯案例</h3><p>输入：热解温度 500 °C，pH 5，初始浓度 40 mg/L，BET 208.4 m²/g。选中 8–16 mg/g 区间，全局近邻 QG = 7 mg/g，区间近邻 QB = 10 mg/g。</p><p class="formula">10<sup>0.4</sup> × 7<sup>0.6</sup> ≈ 8.07 mg/g</p><p>本例 α = 0.4，k = 1，实验 Qe = 8.07 mg/g。本例展示推理路径，不能代表整体误差或对未知材料的保证。</p>`},
metal:{label:'VALIDATION / METAL ADSORPTION',title:'Pb & Cd.<br>Independent evaluation.',body:`<p>数据共 556 条，其中 Pb 349 条、Cd 207 条。开发集 445 条，独立留出集 111 条（Pb 70、Cd 41）。</p><table><thead><tr><th>方法</th><th>MAE</th><th>置信区间</th></tr></thead><tbody><tr><td>JEV</td><td>0.111</td><td>0.076–0.152</td></tr><tr><td>Nearest neighbour</td><td>0.119</td><td>0.084–0.160</td></tr><tr><td>LightGBM</td><td>0.123</td><td>0.091–0.159</td></tr></tbody></table><p>误差值沿用项目评估尺度。JEV 的 R² 为 0.918；分金属 R²：Pb 0.828，Cd 0.926。</p><p>各方法的 MAE 置信区间重叠，当前结果不能据此宣称 JEV 具有统计显著优势。对新材料和新实验条件的表现仍需外部验证。</p>`},
organic:{label:'VALIDATION / ORGANIC CONTEXTS',title:'Adapting through<br>labelled context.',body:`<p>有机物 EC 独立留出集包含 98 条记录、14 类污染物。该评估使用有标签的目标情境上下文，因此不是零样本迁移。</p><table><thead><tr><th>方法</th><th>MAE</th></tr></thead><tbody><tr><td>Geometric midpoint</td><td>0.252</td></tr><tr><td>Nearest neighbour</td><td>0.152</td></tr><tr><td>Fusion</td><td>0.148</td></tr></tbody></table><p>融合的 R² 为 0.777。误差值沿用项目评估尺度；结论仅适用于当前数据划分与有标签上下文设置。</p><h3>以情境适配支持迁移</h3><p>目标实验条件和已知标签为容量区间与候选检索提供上下文。拓展到新的污染物类别，仍需要验证其数据覆盖与实验可比性。</p>`},
case:{label:'TRACEABLE EXAMPLE / PB',title:'279 records.<br>A visible decision path.',body:`<p>从 279 个全局候选中，以所选 8–16 mg/g 容量区间筛出 77 个候选，再依据描述符距离选择近邻。</p><p>全局近邻为第 1 名，QG = 7 mg/g；区间近邻为全局距离排序第 3 名，QB = 10 mg/g。α = 0.4、k = 1 时，融合得到 QF ≈ 8.07 mg/g。</p><img src="assets/pb-candidate-cloud.svg" alt="279 条 Pb 候选的真实容量分布与近邻标记"><p>该样本实验 Qe 为 8.07 mg/g。它用于说明路径可追溯，不能替代整体性能评估。</p><a class="outline-button" href="assets/pb-candidate-rank-qe.csv" download>DOWNLOAD DATA <span>↓</span></a>`}
};
function openDialog(d){d.showModal();document.body.classList.add('modal-open')}
function closeDialog(d){d.close();document.body.classList.remove('modal-open')}
all('dialog').forEach(d=>{d.addEventListener('close',()=>document.body.classList.remove('modal-open'));d.querySelector('[data-close]').addEventListener('click',()=>closeDialog(d));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}})});
function showDetail(key){const t=details[key];$('#detail-content').innerHTML=`<p class="eyebrow">${t.label}</p><h2>${t.title}</h2>${t.body}`;openDialog(dialog);dialog.scrollTop=0}
all('[data-detail]').forEach(b=>b.addEventListener('click',()=>showDetail(b.dataset.detail)));
$('#open-menu').addEventListener('click',()=>openDialog($('#navigation-dialog')));
all('#navigation-dialog nav a').forEach(a=>a.addEventListener('click',()=>closeDialog($('#navigation-dialog'))));
const notes={metal:'MAE 置信区间存在重叠；不据此宣称统计显著优势。误差数值采用项目评估尺度。',organic:'使用有标签的目标情境上下文，并非零样本迁移。结果对应当前 EC 留出集。',case:'示例展示完整证据链，不代表整体误差。候选数据可下载复核。'};
let selected='metal';
function cover(key){const head=`<svg class="chart-cover" viewBox="0 0 480 540" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${key==='metal'?'金属留出集 MAE 与置信区间':key==='organic'?'有机物留出集 MAE 比较':'Pb 案例证据融合'}"><rect x="30" y="25" width="420" height="490" fill="white"/><text x="61" y="61" font-family="Arial" font-size="10" fill="#c8005f" letter-spacing="2">JEV / RESEARCH EVIDENCE</text>`;let b='';
if(key==='case'){b=`<text x="61" y="111" font-size="34" fill="#182f54" font-family="Arial">A traceable estimate.</text><text x="61" y="139" font-size="12" fill="#777" font-family="Arial">Pb · 279 candidates · 77 in range</text><path d="M110 260 Q240 180 365 260M110 260 Q240 360 365 260" fill="none" stroke="#ccd1db" stroke-width="2"/><circle cx="110" cy="260" r="38" fill="#182f54"/><circle cx="365" cy="260" r="38" fill="#c8005f"/><circle cx="237" cy="260" r="48" fill="#f4e6ed"/><g font-family="Arial" text-anchor="middle"><text x="110" y="268" fill="white" font-size="25">7</text><text x="365" y="268" fill="white" font-size="25">10</text><text x="237" y="268" fill="#c8005f" font-size="29">8.07</text><text x="110" y="323" fill="#777" font-size="10">GLOBAL QG</text><text x="365" y="323" fill="#777" font-size="10">RANGE QB</text><text x="237" y="380" fill="#182f54" font-size="15">QF = 10⁰·⁴ × 7⁰·⁶</text></g><text x="61" y="454" font-family="Arial" font-size="10" fill="#777">α = 0.4 · k = 1 · Qe in mg/g</text>`}else{const metal=key==='metal',values=metal?[.111,.119,.123]:[.252,.152,.148],labels=metal?['JEV','Nearest neighbour','LightGBM']:['Geometric midpoint','Nearest neighbour','Fusion'],max=metal?.18:.30;b=`<text x="61" y="110" font-family="Arial" font-size="33" fill="#182f54">${metal?'Pb & Cd holdout.':'Organic adaptation.'}</text><text x="61" y="139" font-family="Arial" font-size="12" fill="#777">${metal?'111 samples · MAE with confidence intervals':'98 samples · 14 categories · MAE'}</text>`;for(let j=0;j<4;j++){const x=70+j*107;b+=`<path d="M${x} 178V365" stroke="#e8eaf0"/><text x="${x}" y="386" text-anchor="middle" font-size="10" font-family="Arial" fill="#888">${(j*max/3).toFixed(2)}</text>`}values.forEach((v,i)=>{const y=202+i*64,w=v/max*321,c=(metal?i===0:i===2)?'#c8005f':'#182f54';b+=`<text x="70" y="${y-9}" fill="#182f54" font-size="11" font-family="Arial">${labels[i]}</text><rect x="70" y="${y}" width="${w}" height="16" fill="${c}"/><text x="${Math.min(405,80+w)}" y="${y+12}" fill="${c}" font-size="12" font-family="Arial">${v.toFixed(3)}</text>`;if(metal){const lows=[.076,.084,.091],highs=[.152,.16,.159],xl=70+lows[i]/max*321,xh=70+highs[i]/max*321;b+=`<path d="M${xl} ${y+8}H${xh}M${xl} ${y+2}V${y+14}M${xh} ${y+2}V${y+14}" stroke="#4d5970" stroke-width="1.5"/>`}});b+=`<text x="61" y="443" font-size="37" fill="#c8005f" font-family="Arial">R² ${metal?'0.918':'0.777'}</text><text x="61" y="470" fill="#888" font-size="10" font-family="Arial">${metal?'Confidence intervals overlap.':'Labelled target context; not zero-shot.'}</text>`}return head+b+'</svg>'}
function selectEvidence(key){selected=key;all('.evidence-row').forEach(b=>{const a=b.dataset.evidence===key;b.classList.toggle('active',a);b.setAttribute('aria-pressed',a)});$('#evidence-feature').innerHTML=cover(key);$('#evidence-note').textContent=notes[key]}
all('.evidence-row').forEach(b=>{['mouseenter','focus','click'].forEach(event=>b.addEventListener(event,()=>selectEvidence(b.dataset.evidence)))});$('#evidence-details').addEventListener('click',()=>showDetail(selected));selectEvidence('metal');
const figures=['fig1_jev_evidence_and_choice','fig2_jev_range_filter_and_fusion','fig3_jev_improvement_and_benchmarks','fig4_jev_probability_and_confidence','fig5_jev_validation_and_context_adaptation'];const titles=['Evidence & choice / 证据构建与选择','Range & fusion / 区间筛选与融合','Improvement & benchmarks / 改进与基准','Probability & confidence / 概率与置信判断','Validation & adaptation / 验证与情境适配'];
all('[data-figure]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.figure)-1,base='assets/research/'+figures[i];$('#figure-label').textContent='JEV RESEARCH / FIGURE 0'+(i+1);$('#figure-title').textContent=titles[i];$('#figure-image').src=base+'.svg';$('#figure-image').alt=titles[i];$('#figure-pdf').href=base+'.pdf';$('#figure-svg').href=base+'.svg';openDialog($('#figure-dialog'));$('#figure-dialog').scrollTop=0}));
['prev','next'].forEach((k,i)=>$('#library-'+k).addEventListener('click',()=>{const track=$('#library-track');track.scrollBy({left:(track.querySelector('button').offsetWidth+25)*(i?1:-1),behavior:'smooth'})}));
let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;function motion(){const b=$('#motion-toggle');b.setAttribute('aria-pressed',paused);b.innerHTML=(paused?'▶':'Ⅱ')+' <span>'+(paused?'PLAY MOTION':'PAUSE MOTION')+'</span>';window.JEVScene?.setPaused(paused)}$('#motion-toggle').addEventListener('click',()=>{paused=!paused;motion()});motion();
let ticking=false;function update(){const r=$('#about').getBoundingClientRect(),progress=Math.max(0,Math.min(1,-r.top/(r.height-innerHeight)));$('#about').style.setProperty('--progress',progress);$('#header').classList.toggle('dark',r.top<82&&r.bottom>100);$('.back-top').classList.toggle('visible',scrollY>innerHeight*.8);if(innerWidth>650&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const rr=$('#research').getBoundingClientRect(),p=Math.max(-1,Math.min(1,(innerHeight*.55-rr.top-rr.height*.45)/innerHeight));all('.research-card').forEach((b,i)=>b.style.setProperty('--shift',((i===1?-1:1)*p*42)+'px'))}ticking=false}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(update);ticking=true}},{passive:true});addEventListener('resize',update);update();
})();
